-- Synthetic staging schema only. Never a production restore or migration baseline.
CREATE TABLE IF NOT EXISTS users(id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,email text UNIQUE NOT NULL,display_name text NOT NULL,role text NOT NULL DEFAULT 'user',avatar_url text,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS sessions(id text PRIMARY KEY,user_id integer NOT NULL REFERENCES users(id),created_at timestamptz DEFAULT now(),last_accessed timestamptz DEFAULT now(),expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS login_attempts(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,email text NOT NULL,attempted_at timestamptz DEFAULT now(),success boolean DEFAULT false);
CREATE TABLE IF NOT EXISTS service_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),job_number bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,data jsonb NOT NULL,calendar_eligible boolean DEFAULT false,version integer DEFAULT 1,synced_version integer DEFAULT 0,event_id text,remote_etag text,sync_error text,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS calendar_connection(id integer PRIMARY KEY,email text NOT NULL,calendar_id text DEFAULT '',last_sync timestamptz,sync_error text,subscription_expires timestamptz,subscription_id text,lock_until timestamptz,webhook_base text,webhook_secret text DEFAULT 'staging-disabled');
CREATE TABLE IF NOT EXISTS calendar_sync_settings(id integer PRIMARY KEY,enabled boolean NOT NULL DEFAULT false CHECK(enabled=false),updated_at timestamptz DEFAULT now());
INSERT INTO calendar_sync_settings(id,enabled) VALUES(1,false) ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS sheet_import_state(id integer PRIMARY KEY,enabled boolean NOT NULL DEFAULT false CHECK(enabled=false),last_error text,last_fetched_at timestamptz,last_import_at timestamptz,last_summary jsonb DEFAULT '{}');
INSERT INTO sheet_import_state(id,enabled) VALUES(1,false) ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS sheet_import_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),started_at timestamptz NOT NULL,finished_at timestamptz DEFAULT now(),result jsonb DEFAULT '{}',error text);
CREATE TABLE IF NOT EXISTS sheet_job_sources(job_id uuid PRIMARY KEY REFERENCES service_jobs(id),source_key text UNIQUE,baseline_data jsonb NOT NULL,raw_data jsonb NOT NULL,conflicts jsonb DEFAULT '{}',missing_source boolean DEFAULT false,updated_at timestamptz DEFAULT now());
